dashboard.definition:
{
    "title": "Intensivstation (PDMS)",
    "description": "Intensivmedizin: Vitalwerte je Bett aus dem PDMS, NEWS2, Beatmungsgeraete und Verbindungsstatus",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Zeitraum",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        },
        "input_bed": {
            "type": "input.dropdown",
            "title": "Bett (Verlauf)",
            "dataSources": {
                "primary": "ds_bed_list"
            },
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "bed",
                "defaultValue": "*"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [
                    [
                        "Stationsmittel (alle Betten)"
                    ],
                    [
                        "*"
                    ]
                ],
                "label": ">primary | seriesByName(\"bed\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"bed\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            }
        },
        "input_vent": {
            "type": "input.dropdown",
            "title": "Beatmung (Monitorwand)",
            "options": {
                "token": "vent",
                "defaultValue": "*",
                "items": [
                    {
                        "label": "Alle Betten",
                        "value": "*"
                    },
                    {
                        "label": "Beatmet",
                        "value": "true"
                    },
                    {
                        "label": "Nicht beatmet",
                        "value": "false"
                    }
                ]
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        },
        "tokens": {
            "default": {
                "bed": {
                    "value": "*"
                },
                "vent": {
                    "value": "*"
                }
            }
        }
    },
    "dataSources": {
        "ds_latest": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:pdms:vitals\" earliest=-10m\n| stats latest(hr) as hr latest(spo2) as spo2 latest(rr) as rr latest(nibp_sys) as nibp_sys latest(nibp_dia) as nibp_dia latest(temp_c) as temp_c latest(news2) as news2 latest(ventilated) as ventilated latest(rhythm) as rhythm latest(data_status) as data_status latest(patient_id) as patient_id latest(ward) as ward by bed",
                "enableSmartSources": true
            },
            "name": "Vitalwerte (letzte 10 min)"
        },
        "ds_bed_list": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| sort bed | fields bed"
            }
        },
        "ds_wall": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| fillnull value=\"unbekannt\" ventilated | search ventilated=\"$vent$\""
            }
        },
        "ds_k_beds": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| stats count as \"Belegte Betten\""
            }
        },
        "ds_k_vent": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| where ventilated=\"true\" OR ventilated=1 | stats count as Beatmet"
            }
        },
        "ds_k_crit": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| where news2>=7 | stats count as \"NEWS2 >= 7\""
            }
        },
        "ds_k_nodata": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| where data_status!=\"ok\" | stats count as \"Ohne Daten\""
            }
        },
        "ds_k_spo2": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.icu.spo2\" span=10m | rename v as \"SpO2 Mittel\"",
                "enableSmartSources": true
            }
        },
        "ds_k_news": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.icu.news2\" span=10m | rename v as \"NEWS2 Mittel\"",
                "enableSmartSources": true
            }
        },
        "ds_heat_hr": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as value WHERE index=demo_sakh_metrics metric_name=\"sakh.icu.hr\" BY bed span=10m\n| timechart span=10m limit=0 avg(value) by bed",
                "enableSmartSources": true
            },
            "name": "Herzfrequenz je Bett"
        },
        "ds_heat_news": {
            "type": "ds.search",
            "options": {
                "query": "| mstats max(_value) as value WHERE index=demo_sakh_metrics metric_name=\"sakh.icu.news2\" BY bed span=10m\n| timechart span=10m limit=0 max(value) by bed",
                "enableSmartSources": true
            }
        },
        "ds_bed": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name IN (\"sakh.icu.hr\", \"sakh.icu.spo2\", \"sakh.icu.rr\", \"sakh.icu.nibp_sys\") bed=\"$bed$\" BY metric_name span=5m\n| eval scope=if(\"$bed$\"=\"*\", \"Mittel\", \"$bed$\"), series=scope.\" · \".case(metric_name=\"sakh.icu.hr\", \"HF\", metric_name=\"sakh.icu.spo2\", \"SpO2\", metric_name=\"sakh.icu.rr\", \"AF\", true(), \"RR sys\")\n| timechart span=5m avg(v) by series",
                "enableSmartSources": true
            },
            "name": "Verlauf ausgewaehltes Bett"
        },
        "ds_vent": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:medtech:telemetry\" device_type=VENT department=ICU earliest=-15m\n| stats latest(in_use) as in_use latest(mode) as Modus latest(fio2_pct) as \"FiO2 %\" latest(peep_cmh2o) as PEEP latest(tidal_volume_ml) as \"Vt ml\" latest(status) as Status latest(connectivity) as Verbindung latest(manufacturer) as Hersteller latest(model) as Modell by device_id ward\n| where in_use=\"true\" OR Status=\"Offline\" | fields - in_use | rename device_id as Geraet ward as Station",
                "enableSmartSources": true
            }
        },
        "ds_alarms": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:pdms:vitals\" alarm!=\"keiner\" alarm=*\n| stats count as Alarme latest(news2) as \"NEWS2 zuletzt\" latest(alarm) as Stufe by bed | sort - Alarme | head 15 | rename bed as Bett",
                "enableSmartSources": true
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_klinik/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_klinik",
                        "dashboard": "kis_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
