                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#0b7fab"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 2,
                        "value": "#1e8a5a"
                    },
                    {
                        "from": 2,
                        "to": 4,
                        "value": "#c98a00"
